; Stop the SID voices
; $7cdf-$7d02

; Stops SID voice 1. It sets and clears the test bit of the voice control register.
stop_voice1
        ldx #$04
        bne stop_voice_x
; Stops SID voice 2.
stop_voice2
        ldx #$0b
        bne stop_voice_x
; Stops SID voice 3.
stop_voice3
        ldx #$12
stop_voice_x
        lda #$08                        ; X is the register offset of the voice.
        sta FRELO1,x
        lda #$00
        sta FRELO1,x
        rts
; Stops the three voices and sets the SID volume to 15 with filter mode bit 6.
stop_all_sound
        jsr stop_voice1
        jsr stop_voice2
        jsr stop_voice3
        lda #$4f
        sta SIGVOL
        rts
